VALUES (NULL, NULL, 8600, 'Fear Effect', 'Fear Effect', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8j85.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf3yo.jpg', 'Fear Effect is an action adventure waiting to unfold! Wee Ming Lam disappears a few days before her 18th birthday under mysterious circumstances. Three ruthless mercenaries conspire to track her down and ransom her off to her father, Mr. Lam, a powerful Triad leader in Hong Kong. An extortion mission to retrieve Wee Ming Lam becomes a lesson in survival against the most unimaginable of enemies.', 'https://www.igdb.com/games/fear-effect', '["PlayStation 3", "PlayStation"]', NULL, 7.5, 0, 9.03, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
