VALUES (NULL, NULL, 290911, 'Nobody Wants to Die', 'Nobody Wants to Die', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7w0e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5lr8.jpg', 'Lose yourself in the dystopian world of New York, 2329; immortality comes at a price that someone has to pay. In this interactive noir story, lead the investigation using advanced technology, as Detective James Karra who risks it all in pursuit of a serial killer targeting the city’s elite.', 'https://www.igdb.com/games/nobody-wants-to-die', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.6, 0, 9.55, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
