VALUES (NULL, NULL, 11169, 'Final Fantasy VII Remake', 'Final Fantasy VII Remake', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobcwt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5c45.jpg', 'A modern reimagining of one of the most iconic games of all time, Final Fantasy VII Remake harnesses the very latest technology to recreate and expand Square Enix''s legendary RPG adventure for the current generation. Set in a post-industrial fantasy world that has fallen under the control of the shadowy Shinra Electric Power Company, take on the role of Cloud Strife - a mercenary and former member of Shinra''s elite Soldier unit - and team up with anti-Shinra organization Avalanche as they step-up their resistance.', 'https://www.igdb.com/games/final-fantasy-vii-remake', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.9, 0, 9.09, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
