VALUES (NULL, NULL, 129128, 'Colony Ship: A Post-Earth Role Playing Game', 'Colony Ship: A Post-Earth Role Playing Game', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xue.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar54zx.jpg', 'Colony Ship is a turn-based, party-based role-playing game set aboard a generation ship launched to Proxima Centauri. The game features a detailed skill-based character system, multiple ways to handle quests, choices & consequences, and branching dialogue trees.', 'https://www.igdb.com/games/colony-ship-a-post-earth-role-playing-game', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 8.01, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
