VALUES (NULL, NULL, 7120, 'NieR', 'NieR', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coapbf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7gy.jpg', 'Nothing is as it seems in Square Enix''s latest action adventure game, set in a crumbling world plagued by disease and dark, unrecognizable creatures. Players assume the role of the unyielding protagonist, NIER, resolute in his quest to discover a cure for his daughter, who is infected with the Black Scrawl virus. With powerful allies and a mysterious book, NIER encounters things that will confound even the mightiest of warriors. With NIER, experience seamless in-battle cinematics and explore hauntingly familiar lands, intense action-packed battles, and storytelling like only Square Enix can do', 'https://www.igdb.com/games/nier', '["PlayStation 3", "Xbox 360", "Xbox One"]', NULL, 7.5, 0, 8.01, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
