VALUES (NULL, NULL, 1105, 'Metroid Prime', 'Metroid Prime', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3w4w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/a0lmffyqmm3wqgzdistt.jpg', 'A 3D exploration-focused metroidvania with first-person shooting mechanics and the first 3D entry in the Metroid series, Metroid Prime follows Samus Aran after the events of Metroid (1986) as she boards a Space Pirate frigate, then chases her escaping archrival Ridley into the intricately structured Tallon IV, a planet full of deadly wildlife and former home to the advanced and ancient Chozo race.', 'https://www.igdb.com/games/metroid-prime', '["Nintendo GameCube"]', NULL, 9.3, 0, 9.03, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
