VALUES (NULL, NULL, 16587, 'Final Fantasy IV', 'Final Fantasy IV', 'game', 1991, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co31c0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5x6w.jpg', 'FINAL FANTASY IV is the fourth main installment in the FINAL FANTASY series, developed and published by Squaresoft. It was released in July 1991 for the Super Nintendo Entertainment System in Japan, and released as FINAL FANTASY II in North America in October 1991 with alterations made due to Nintendo of America''s guidelines at the time.', 'https://www.igdb.com/games/final-fantasy-iv--1', '["Wii", "Wii U", "New Nintendo 3DS", "Super Famicom"]', NULL, 8.2, 0, 9.05, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
