VALUES (NULL, NULL, 1134, 'Castlevania: Aria of Sorrow', 'Castlevania: Aria of Sorrow', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob947.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar63lw.jpg', 'The year is 2035 and Soma Cruz is about to witness the first solar eclipse of the 21st century when he suddenly blacks out -- only to awaken inside a mysterious castle. As Soma, you must navigate the castle''s labyrinths while confronting perilous monsters at every turn. But beware, you must escape before the evil consumes you!', 'https://www.igdb.com/games/castlevania-aria-of-sorrow', '["Wii U", "Game Boy Advance"]', NULL, 8.7, 0, 8.02, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
