VALUES (NULL, NULL, 36550, 'Yakuza: Like a Dragon', 'Yakuza: Like a Dragon', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2em9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar48ey.jpg', 'Yakuza: Like a Dragon is a role-playing game developed and published by Sega. Released in 2020, it is the eighth main entry in the Yakuza series. The game introduces a new protagonist, Ichiban Kasuga, and departs from the traditional action combat system, instead featuring turn-based combat with a party of characters. Set in the city of Yokohama, the game follows Kasuga''s quest for revenge and his journey through Japan''s criminal underworld.', 'https://www.igdb.com/games/yakuza-like-a-dragon', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.5, 0, 9.05, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
