VALUES (NULL, NULL, 112348, 'The Last Sovereign', 'The Last Sovereign', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co43wp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arivu.jpg', 'The Last Sovereign is an adult fantasy RPG that twists your expectations for adult games, while fully embracing a reconstruction of some familiar old tropes to provide a lot of fun, sexy content.', 'https://www.igdb.com/games/the-last-sovereign', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 0.0, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
