VALUES (NULL, NULL, 13204, 'Pathologic Classic HD', 'Pathologic Classic HD', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob0w1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4j01.jpg', 'In Pathologic players embark on a dark journey to explore a remote town built upon old tanneries and butcheries just as a mysterious and deadly disease breaks out. Pathologic Classic HD is an extensive remaster of the original game, featuring updated graphics and effects, while addressing the most prominent critiques of the original with a completely redone English script, brand new re-recorded voice-overs and reinstated text and dialogue.', 'https://www.igdb.com/games/pathologic-classic-hd', '["PC (Microsoft Windows)"]', NULL, 7.8, 0, 10.02, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
