VALUES (NULL, NULL, 3998, 'Valkyrie Profile', 'Valkyrie Profile', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u5x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yrzkxquvodd6dxsksmrt.jpg', 'Valkyrie Profile is a role-playing video game developed by tri-Ace and published by Enix (now Square Enix) for the PlayStation. It was released on December 22, 1999 in Japan and on August 29, 2000 in North America. An enhanced port of the game was later released for the PlayStation Portable under the name Valkyrie Profile: Lenneth on March 2, 2006 in Japan, July 18, 2006 in North America, and April 27, 2007 in Europe.', 'https://www.igdb.com/games/valkyrie-profile', '["PlayStation"]', NULL, 8.6, 0, 9.51, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
