VALUES (NULL, NULL, 39, 'Mafia', 'Mafia', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qrt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5kzw.jpg', 'Mafia is a 3D action crime epic set in the seedy underworld of the 1930''s. Rise from the lowly but well-dressed Footsoldier, to an envied and feared Made Man in an era of mob hits, car chases, and bootlegging. Earn a reputation as a tough enforcer, daring getaway driver, and deadly hitman in your quest for respect and power within the Salieri Family.', 'https://www.igdb.com/games/mafia', '["Xbox", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 7.4, 0, 10.94, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
