VALUES (NULL, NULL, 2059, 'Yakuza', 'Yakuza', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29tp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jcvqpfugxhrdoyurgust.jpg', 'Just as Kazuma, a former rising star in the Yakuza, emerges from prison after a murder cover-up, 10 billion yen vanishes from the Yakuza vault, forcing him once again into their brutal, lawless world. A mysterious young girl will lead Kazuma to the answers if he can keep her alive.', 'https://www.igdb.com/games/yakuza', '["PlayStation 2"]', NULL, 7.7, 0, 8.55, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
