VALUES (NULL, NULL, 119386, 'Empire of Sin', 'Empire of Sin', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nbm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5sn.jpg', 'Empire of Sin, the strategy game from Romero Games and Paradox Interactive, puts you at the heart of the ruthless criminal underworld of 1920s Prohibition-era Chicago.

It’s up to you to hustle, charm and intimidate your way to the top of the pile and do whatever it takes to stay there. This character-driven, noir-inspired game puts players smack dab in the glitz and glamor of the roaring 20s, all while working behind the scenes in the gritty underbelly of organized crime.', 'https://www.igdb.com/games/empire-of-sin', '["PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.2, 0, 10.05, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
