VALUES (NULL, NULL, 51226, 'Gangsters 2: Vendetta', 'Gangsters 2: Vendetta', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5x93.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scorf3.jpg', 'Set from late 1928-early 1929, the game follows a character called ''Joey Bane'' whose nickname is decided by the player e.g. Joey ''Scarface'' Bane. The character''s father is murdered at the beginning by a mob controlling most of New Temperance, the leader of the mob is Frankie ''Hammer'' Constantine. The player progresses through the game by defeating different gangs and gang leaders that are all connected to the killing of Joey Bane''s father.', 'https://www.igdb.com/games/gangsters-2-vendetta', '["PC (Microsoft Windows)"]', NULL, 9.1, 0, 9.02, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
