VALUES (NULL, NULL, 2482, 'The Godfather', 'The Godfather', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4dyp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scfbkm.jpg', 'The Godfather puts you into the action of the legendary films, while you relive the classic moments of the Corleone family. After a life of small-time jobs and petty thefts, you are accepted into the Corleone family -- America''s most famous criminal organization. It will be up to you to carry out orders, earn respect and make New York City your own. Featuring the voices of James Caan and Robert Duvall and the likeness of Marlon Brando.', 'https://www.igdb.com/games/the-godfather--1', '["Xbox", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 7.4, 0, 9.55, '2026-11-23 03:29:46', '2026-11-23 03:29:46')
