VALUES (NULL, NULL, 11772, 'Shadowrun: Hong Kong', 'Shadowrun: Hong Kong', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wg9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6cfy.jpg', 'Shadowrun: Hong Kong is the third standalone game in Harebrained Schemes’ critically-acclaimed Shadowrun cRPG series. Experience the most impressive Shadowrun yet with an all new crew, expanded magic and cyberware, a revamped Matrix, an upgraded Shadowrun Editor, and much more!', 'https://www.igdb.com/games/shadowrun-hong-kong', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.0, 0, 1.15166666666666657e+01, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
