VALUES (NULL, NULL, 121752, 'Ghostrunner', 'Ghostrunner', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nbk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6q7.jpg', 'Ascend humanity’s last remaining shelter, a great tower-city. The tower is torn by violence, poverty and chaos. Conquer your enemies, discover the secrets of the superstructure and your own origin and obtain the power to challenge The Keymaster.', 'https://www.igdb.com/games/ghostrunner', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 1.05266666666666672e+01, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
