VALUES (NULL, NULL, 110248, 'Stray', 'Stray', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tt2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1nzp.jpg', 'Stray is a third-person cat adventure game set amidst the detailed neon-lit alleys of a decaying cybercity and the murky environments of its seedy underbelly. Roam surroundings high and low, defend against unforeseen threats and solve the mysteries of this unwelcoming place inhabited by nothing but unassuming droids and dangerous creatures.

See the world through the eyes of a stray and interact with the environment in playful ways. Be stealthy, nimble, silly, and sometimes as annoying as possible with the strange inhabitants of this foreign world.', 'https://www.igdb.com/games/stray', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.3, 0, 8.77, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
