VALUES (NULL, NULL, 544, 'The Darkness II', 'The Darkness II', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mxv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armgb.jpg', 'The Darkness II is an intense first person shooter that delivers a twisted and gripping narrative of tragedy, modern crime drama, and supernatural horror. Players will be taken down the brutal and personal path of Jackie Estacado, head of a New York crime family and wielder of an ancient and ruthless force of chaos and destruction known as The Darkness.', 'https://www.igdb.com/games/the-darkness-ii', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.7, 0, 9.265, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
