VALUES (NULL, NULL, 523, 'Infamous', 'Infamous', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co525t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/v6kmagfvuapw4hsnmxs0.jpg', 'Infamous is a single player open-world action/adventure game that places you in the role of Cole McGrath, a once regular guy who in the aftermath of a horrific catastrophe finds himself not only alive, but developing a fantastic array of superpowers. Going from ordinary to extraordinary overnight isn''t something to take lightly. With these powers does one exact revenge? Protect the innocent? Or perhaps, dabble in a little of both? The choice is yours in Infamous.', 'https://www.igdb.com/games/infamous', '["PlayStation 3"]', NULL, 8.1, 0, 9.265, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
