VALUES (NULL, NULL, 1341, 'Beyond Good & Evil', 'Beyond Good & Evil', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n6b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7uo.jpg', 'Beyond Good & Evil is an action-adventure game with elements of puzzle-solving and stealth-based games. The player controls the protagonist, Jade, from a third-person perspective. Jade can run, move stealthily, jump over obstacles and pits, climb ladders, push or bash doors and objects, and flatten herself against walls. As Jade, the player investigates a number of installations in search of the truth about a war with an alien threat.', 'https://www.igdb.com/games/beyond-good-evil', '["Xbox", "Nintendo GameCube", "PC (Microsoft Windows)", "Xbox 360", "PlayStation 2"]', NULL, 8.8, 0, 10.265, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
