INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 73, 'Mass Effect', 'Mass Effect', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x7o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nh2tkxayf39zfaruit9e.jpg', 'Mass Effect is an action role-playing game set in the year 2183. The player takes the role of Commander Shepard, a customizable character who serves as Executive Officer aboard the SSV Normandy. After a routine mission goes wrong, Shepard assembles a squad and pursues a threat that escalates into a galaxy-wide conflict. The game features real-time squad-based combat where players choose companions and tactics suited to different enemy types, from biotic-wielding opponents to heavily armored machines.

The game spans a large science fiction universe, with explorable locations ranging from the Citadel space station to alien homeworlds and remote outposts. Player decisions affect mission outcomes, crew relationships, and the overarching narrative across the trilogy.', 'https://www.igdb.com/games/mass-effect', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.7, 0, 12.695, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
