VALUES (NULL, NULL, 9789, 'RimWorld', 'RimWorld', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaaqj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardhk.jpg', 'A sci-fi colony sim driven by an intelligent AI storyteller. Generates stories by simulating psychology, ecology, gunplay, melee combat, climate, biomes, diplomacy, interpersonal relationships, art, medicine, trade, and more.', 'https://www.igdb.com/games/rimworld', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.0, 0, 5.51333333333333364e+00, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
