VALUES (NULL, NULL, 119171, 'Baldur''s Gate III', 'Baldur''s Gate III', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co670h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3n2t.jpg', 'An ancient evil has returned to Baldur''s Gate, intent on devouring it from the inside out. The fate of Faerun lies in your hands. Alone, you may resist. But together, you can overcome.', 'https://www.igdb.com/games/baldurs-gate-iii', '["Google Stadia", "Xbox Series X|S", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 9.5, 0, 10.612, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
