VALUES (NULL, NULL, 127254, 'Pathfinder: Wrath of the Righteous', 'Pathfinder: Wrath of the Righteous', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uq7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arypm.jpg', 'Embark on a journey to a realm overrun by demons in Pathfinder: Wrath of the Righteous, a new epic RPG from the creators of the critically acclaimed Pathfinder: Kingmaker. Explore the nature of good and evil, learn the true cost of power, and rise as a Mythic Hero capable of deeds beyond mortal expectations.', 'https://www.igdb.com/games/pathfinder-wrath-of-the-righteous', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.7, 0, 1.21228571428571427e+01, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
