VALUES (NULL, NULL, 19560, 'God of War', 'God of War', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkt6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tvl9vif6lw8sckkqyaj7.jpg', 'God of War is the sequel to God of War III as well as a continuation of the canon God of War chronology. Unlike previous installments, this game focuses on Norse mythology and follows an older and more seasoned Kratos and his son Atreus in the years since the third game. It is in this harsh, unforgiving world that he must fight to survive… and teach his son to do the same.', 'https://www.igdb.com/games/god-of-war--1', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.4, 0, 7.888, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
