VALUES (NULL, NULL, 40, 'Mafia II', 'Mafia II', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n13.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpce.jpg', 'Mafia II is a third-person action-adventure game set in the fictional American city of Empire Bay between 1945 and 1951. Players control Vito Scaletta through a story-driven campaign involving organized crime, navigating an open world on foot or by vehicle. Gameplay combines shooting, driving, and limited melee combat, with a wanted system that escalates law enforcement response based on criminal activity. The game features era-appropriate vehicles, licensed period music across multiple radio stations, and a cover-based combat system.', 'https://www.igdb.com/games/mafia-ii', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.7, 0, 6.535, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
