VALUES (NULL, NULL, 6057, 'Shadow Warrior', 'Shadow Warrior', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91kp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar69f.jpg', 'Shadow Warrior is a bold reimagining of the 3D Realms'' cult classic shooter from independent developer Flying Wild Hog (Hard Reset) starring the legendary and quick-witted warrior Lo Wang. Combine the brute force of overwhelming firepower with the elegant precision of a katana to annihilate the merciless armies of the shadow realm in an exhilarating and visually stunning transformation of the classic first-person shooter.', 'https://www.igdb.com/games/shadow-warrior-4a585c08-b9c8-4f94-9bed-4461ac7e6a4c', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 7.3, 0, 5.01500000000000056e+00, '2026-11-19 20:56:22', '2026-11-23 03:29:46')
