VALUES (NULL, NULL, 142186, 'Peripeteia', 'Peripeteia', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nn0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4g98.jpg', 'Peripeteia is a first-person game mixing shooter, stealth and RPG mechanics, placing it within the elusive and ephemeral "immersive sim" genre, heavily inspired by the greats such as Deus Ex, it expands upon the formula with original ideas and an unexplored alternative history post-soviet setting.', 'https://www.igdb.com/games/peripeteia', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 11.5625, '2026-11-21 13:07:40', '2026-11-23 03:29:46')
