VALUES (NULL, NULL, 26381, 'TheHunter: Call of the Wild', 'TheHunter: Call of the Wild', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u14.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/udfncdif7dcfiypst3j9.jpg', 'Never before have you experienced a hunting game like theHunter: Call of the Wild. Plunge into an atmospheric open world, teeming with life: from the majestic true-to-life animals to the rustling of leaves above you as you stalk your prey. You can decide to hunt on your own or join up and hunt together with friends. Just remember, you are not just a visitor in this world, you are a living and breathing part of it. As you finally spot the majestic crown of your first red deer through the brush, the feeling is indescribable.', 'https://www.igdb.com/games/thehunter-call-of-the-wild', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.2, 0, 5.72, '2026-11-21 21:29:28', '2026-11-23 03:29:46')
