VALUES (NULL, NULL, 18294, 'The Punisher', 'The Punisher', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p2u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/unxt5gk2ed0sbq6pjyyf.jpg', 'Crime is everywhere on the streets of New York City. As Frank "the Punisher" Castle, it is your job to clean them up. However, there seem to be bigger things at hand...', 'https://www.igdb.com/games/the-punisher--1', '["Xbox", "PC (Microsoft Windows)", "Xbox 360", "Legacy Mobile Device", "PlayStation 2"]', NULL, 7.9, 0, 6.01, '2026-11-22 03:06:26', '2026-11-23 03:29:46')
